    # 审计：成功并分配新 rev 时追加（仅留最近 64 条），section 取被
    # 替换顶层字段；before/after 即响应中的 base/target 摘要（值未变
    # 两摘要相同仍记录）。
    audit_events.append(
        {
            "rev": new_rev,
            "now": now,
            "kind": "cu",
            "section": section,
            "before": before_digest,
            "after": target_digest,
        }
    )
    results.append(
        {
            "op": "cu",
